def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []

    for i, operation in enumerate(ops):
        tokens = operation.split()
        if not tokens:
            rejected.append(i)
            continue

        verb = tokens[0]
        record = None

        if verb == "open" and len(tokens) == 3:
            name, raw = tokens[1], tokens[2]
            if raw.isascii() and raw.isdigit():
                amount = int(raw)
                if name not in accounts:
                    accounts[name] = [amount, False]
                    record = ("open", name)

        elif verb == "deposit" and len(tokens) == 3:
            name, raw = tokens[1], tokens[2]
            if raw.isascii() and raw.isdigit():
                amount = int(raw)
                if amount > 0 and name in accounts:
                    accounts[name][0] += amount
                    record = ("balance", name, -amount)

        elif verb == "withdraw" and len(tokens) == 3:
            name, raw = tokens[1], tokens[2]
            if raw.isascii() and raw.isdigit():
                amount = int(raw)
                if (amount > 0 and name in accounts and
                        not accounts[name][1] and accounts[name][0] >= amount):
                    accounts[name][0] -= amount
                    record = ("balance", name, amount)

        elif verb == "transfer" and len(tokens) == 4:
            source, target, raw = tokens[1], tokens[2], tokens[3]
            if raw.isascii() and raw.isdigit():
                amount = int(raw)
                if (amount > 0 and source != target and source in accounts and
                        target in accounts and not accounts[source][1] and
                        accounts[source][0] >= amount):
                    accounts[source][0] -= amount
                    accounts[target][0] += amount
                    record = ("transfer", source, target, amount)

        elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
            name = tokens[1]
            if name in accounts:
                old_state = accounts[name][1]
                if (verb == "freeze" and not old_state) or (verb == "unfreeze" and old_state):
                    accounts[name][1] = not old_state
                    record = ("frozen", name, old_state)

        elif verb == "undo" and len(tokens) == 1:
            if history:
                record = history.pop()
                kind = record[0]
                if kind == "open":
                    del accounts[record[1]]
                elif kind == "balance":
                    accounts[record[1]][0] += record[2]
                elif kind == "transfer":
                    _, source, target, amount = record
                    accounts[source][0] += amount
                    accounts[target][0] -= amount
                elif kind == "frozen":
                    accounts[record[1]][1] = record[2]
            else:
                rejected.append(i)

        else:
            pass

        if verb != "undo":
            if record is None:
                rejected.append(i)
            else:
                history.append(record)

    return ({name: data[0] for name, data in accounts.items()}, rejected)
